import os
"""Independent Python plist/AEAD fixtures; not generated by the C++ under test."""
from pathlib import Path
import plistlib, struct, subprocess, re, hashlib, json
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305

root = Path(__file__).resolve().parents[2]
out = root / '../build/carplay/windows-x64/fixtures'
out.mkdir(parents=True, exist_ok=True)
value = {'name': 'Windows 车机 🚗', 'enabled': True, 'number': 0xFEDCBA9876543210,
         'data': bytes(range(256)), 'array': [1, False, ''], 'nested': {'key': 'a&<b>'}}
for fmt, ext in [(plistlib.FMT_BINARY, 'bplist'), (plistlib.FMT_XML, 'xml')]:
    (out / ('independent.'+ext)).write_bytes(plistlib.dumps(value, fmt=fmt))
ffmpeg = os.environ.get('CARPLAY_FFMPEG', 'ffmpeg')
# Development fixture generation only; the receiver never launches this tool.
subprocess.run([ffmpeg,'-hide_banner','-loglevel','error','-y','-f','lavfi','-i',
               'sine=frequency=440:sample_rate=48000:duration=2','-ac','2','-c:a','aac',
               '-f','adts',str(out/'reference.aac')],check=True)
subprocess.run([ffmpeg,'-hide_banner','-loglevel','error','-y','-f','lavfi','-i',
               'testsrc2=size=800x480:rate=30','-frames:v','30','-c:v','libx264',
               '-preset','ultrafast','-tune','zerolatency','-pix_fmt','yuv420p',
               '-f','h264',str(out/'reference.h264')], check=True)
raw = (out/'reference.h264').read_bytes()
units = [n for n in re.split(b'\x00\x00\x00?\x01',raw) if n]
sps=next(n for n in units if n[0]&31==7)
pps=next(n for n in units if n[0]&31==8)
avcc = bytes([1,sps[1],sps[2],sps[3],255,225])+struct.pack('>H',len(sps))+sps+bytes([1])+struct.pack('>H',len(pps))+pps
key=bytes(range(32))
(out/'expansion.bplist').write_bytes(plistlib.dumps([b'x'*32768]*1024,fmt=plistlib.FMT_BINARY))
packets=[]
header=struct.pack('<IB',len(avcc),1)+bytes(123)
packets.append(header+avcc)
nonce=0
for n in units:
    if n[0]&31 in (7,8): continue
    payload=struct.pack('>I',len(n))+n
    header=struct.pack('<IB',len(payload)+16,0)+bytes(123)
    sealed=ChaCha20Poly1305(key).encrypt(bytes(4)+struct.pack('<Q',nonce),payload,header)
    packets.append(header+sealed)
    nonce+=1
(out/'screen.bin').write_bytes(b''.join(packets))
(out/'key.bin').write_bytes(key)
manifest={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in out.iterdir() if p.is_file()}
(out/'manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
print('Created independent binary/XML plists and 30 H.264 frames in encrypted screen packets')
